// Group queued items by account (GiveSendGo first) into ONE Sonnet prompt.
const items = $input.all().map(i => i.json);
if (items.length === 0) {
  return [{ json: { synthSystem: 'You are a Chief of Staff.', synthUser: 'There are no new items today. Reply with a single short line saying the inbox is clear.' } }];
}
const order = { givesendgo: 1, gmail: 2, outlook: 3, nextcloud: 4 };
items.sort((a, b) => (a.priority - b.priority) || ((order[a.account] || 9) - (order[b.account] || 9)));
const byAccount = {};
for (const it of items) { (byAccount[it.account] = byAccount[it.account] || []).push(it); }
const accounts = Object.keys(byAccount).sort((a, b) => (order[a] || 9) - (order[b] || 9));
let input = '';
for (const acc of accounts) {
  input += '\n## ' + acc + '\n';
  for (const it of byAccount[acc]) {
    input += '- [' + it.classification + '] ' + (it.from_addr || '') + ' \u2014 ' + (it.subject || '') + ' :: ' + (it.one_line || '') + '\n';
  }
}
const synthSystem = 'You are a Chief of Staff writing one concise daily morning brief. Group strictly by account in the order given. GiveSendGo Charities MUST appear first. Within each account, list needs_reply items before fyi. Be terse and scannable, markdown headers, no invented items.';
const synthUser = 'Write the morning brief from these triaged items, grouped by account (GiveSendGo first):\n' + input;
return [{ json: { synthSystem, synthUser } }];

// Pull the brief text out of the Sonnet response.
let text = '';
try { text = $input.first().json.content[0].text; } catch (e) { text = '(no brief generated)'; }
return [{ json: { brief: text } }];
